ALTER TABLE public.budgets ADD COLUMN approval_date date, ADD COLUMN approval_path text;
CREATE TABLE public.works (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), budget_id uuid NOT NULL UNIQUE REFERENCES public.budgets(id), name text NOT NULL, client_id uuid REFERENCES public.people(id), architect_id uuid REFERENCES public.people(id), address text, responsible text, planned_start date, planned_end date, actual_start date, actual_end date, status text NOT NULL DEFAULT 'contratacao' CHECK(status IN ('contratacao','execucao','pausada','concluida')), archived boolean NOT NULL DEFAULT false, created_by uuid, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.works TO authenticated; GRANT ALL ON public.works TO service_role;
ALTER TABLE public.works ENABLE ROW LEVEL SECURITY;
CREATE POLICY works_read ON public.works FOR SELECT TO authenticated USING (public.can_see_costs(auth.uid()) OR public.has_role(auth.uid(),'equipe'));
CREATE POLICY works_write ON public.works FOR ALL TO authenticated USING(public.can_see_costs(auth.uid())) WITH CHECK(public.can_see_costs(auth.uid()));
CREATE TRIGGER works_audit BEFORE INSERT OR UPDATE ON public.works FOR EACH ROW EXECUTE FUNCTION public.touch_audit();
CREATE TABLE public.contracts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), work_id uuid NOT NULL UNIQUE REFERENCES public.works(id), body text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'rascunho' CHECK(status IN ('rascunho','gerado','assinado')), signed_path text, signed_date date, created_by uuid, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.contracts TO authenticated; GRANT ALL ON public.contracts TO service_role;
ALTER TABLE public.contracts ENABLE ROW LEVEL SECURITY;
CREATE POLICY contracts_read ON public.contracts FOR SELECT TO authenticated USING(public.can_see_costs(auth.uid()));
CREATE POLICY contracts_write ON public.contracts FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TRIGGER contracts_audit BEFORE INSERT OR UPDATE ON public.contracts FOR EACH ROW EXECUTE FUNCTION public.touch_audit();
CREATE TABLE public.work_stages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), work_id uuid NOT NULL REFERENCES public.works(id), budget_section_id uuid REFERENCES public.budget_sections(id), name text NOT NULL, sort int NOT NULL DEFAULT 0, responsible text, planned_start date, planned_end date, actual_start date, actual_end date, dependency_id uuid REFERENCES public.work_stages(id), weight numeric NOT NULL DEFAULT 0 CHECK(weight>=0 AND weight<=100), progress numeric NOT NULL DEFAULT 0 CHECK(progress>=0 AND progress<=100), created_by uuid, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(work_id,budget_section_id));
GRANT SELECT, INSERT, UPDATE ON public.work_stages TO authenticated; GRANT ALL ON public.work_stages TO service_role;
ALTER TABLE public.work_stages ENABLE ROW LEVEL SECURITY;
CREATE POLICY stage_access ON public.work_stages FOR ALL TO authenticated USING(public.can_see_costs(auth.uid()) OR public.has_role(auth.uid(),'equipe')) WITH CHECK(public.can_see_costs(auth.uid()) OR public.has_role(auth.uid(),'equipe'));
CREATE TRIGGER work_stages_audit BEFORE INSERT OR UPDATE ON public.work_stages FOR EACH ROW EXECUTE FUNCTION public.touch_audit();
CREATE TABLE public.work_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), work_id uuid NOT NULL REFERENCES public.works(id), kind text NOT NULL CHECK(kind IN ('diario','entrega','assistencia','decisao','documento')), stage_id uuid REFERENCES public.work_stages(id), record_date date NOT NULL DEFAULT current_date, title text NOT NULL, body text, team text, next_steps text, responsible text, due_date date, status text NOT NULL DEFAULT 'pendente', file_path text, caption text, created_by uuid, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.work_records TO authenticated; GRANT ALL ON public.work_records TO service_role;
ALTER TABLE public.work_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY records_access ON public.work_records FOR ALL TO authenticated USING(public.can_see_costs(auth.uid()) OR public.has_role(auth.uid(),'equipe')) WITH CHECK(public.can_see_costs(auth.uid()) OR public.has_role(auth.uid(),'equipe'));
CREATE TRIGGER records_audit BEFORE INSERT OR UPDATE ON public.work_records FOR EACH ROW EXECUTE FUNCTION public.touch_audit();
CREATE TABLE public.financial_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, opening_balance numeric NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.financial_accounts TO authenticated; GRANT ALL ON public.financial_accounts TO service_role;
ALTER TABLE public.financial_accounts ENABLE ROW LEVEL SECURITY;
CREATE POLICY accounts_access ON public.financial_accounts FOR ALL TO authenticated USING(public.can_see_costs(auth.uid())) WITH CHECK(public.can_see_costs(auth.uid()));
CREATE TABLE public.purchase_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), work_id uuid NOT NULL REFERENCES public.works(id), supplier_id uuid REFERENCES public.people(id), description text NOT NULL, expected_date date, status text NOT NULL DEFAULT 'pedido' CHECK(status IN ('pedido','parcial','recebido','cancelado')), file_path text, created_by uuid, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.purchase_orders TO authenticated; GRANT ALL ON public.purchase_orders TO service_role;
ALTER TABLE public.purchase_orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY orders_access ON public.purchase_orders FOR ALL TO authenticated USING(public.can_see_costs(auth.uid())) WITH CHECK(public.can_see_costs(auth.uid()));
CREATE TRIGGER orders_audit BEFORE INSERT OR UPDATE ON public.purchase_orders FOR EACH ROW EXECUTE FUNCTION public.touch_audit();
CREATE TABLE public.purchase_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES public.purchase_orders(id), material_key text NOT NULL, name text NOT NULL, unit text NOT NULL, quantity numeric NOT NULL CHECK(quantity>0), unit_price numeric NOT NULL CHECK(unit_price>=0), received numeric NOT NULL DEFAULT 0 CHECK(received>=0 AND received<=quantity));
GRANT SELECT, INSERT, UPDATE ON public.purchase_lines TO authenticated; GRANT ALL ON public.purchase_lines TO service_role;
ALTER TABLE public.purchase_lines ENABLE ROW LEVEL SECURITY;
CREATE POLICY lines_access ON public.purchase_lines FOR ALL TO authenticated USING(public.can_see_costs(auth.uid())) WITH CHECK(public.can_see_costs(auth.uid()));
CREATE TABLE public.material_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), work_id uuid NOT NULL REFERENCES public.works(id), material_key text NOT NULL, kind text NOT NULL CHECK(kind IN ('reserva','consumo','cliente_recebido')), quantity numeric NOT NULL CHECK(quantity>0), record_date date NOT NULL DEFAULT current_date, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.material_movements TO authenticated; GRANT ALL ON public.material_movements TO service_role;
ALTER TABLE public.material_movements ENABLE ROW LEVEL SECURITY;
CREATE POLICY movements_access ON public.material_movements FOR ALL TO authenticated USING(public.can_see_costs(auth.uid())) WITH CHECK(public.can_see_costs(auth.uid()));
CREATE TABLE public.financial_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), work_id uuid REFERENCES public.works(id), stage_id uuid REFERENCES public.work_stages(id), category text NOT NULL DEFAULT 'Outras', description text NOT NULL, person_id uuid REFERENCES public.people(id), direction text NOT NULL CHECK(direction IN ('entrada','saida')), amount numeric NOT NULL CHECK(amount>0), due_date date NOT NULL, incurred boolean NOT NULL DEFAULT false, purchase_order_id uuid REFERENCES public.purchase_orders(id), canceled boolean NOT NULL DEFAULT false, created_by uuid, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.financial_entries TO authenticated; GRANT ALL ON public.financial_entries TO service_role;
ALTER TABLE public.financial_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY entries_access ON public.financial_entries FOR ALL TO authenticated USING(public.can_see_costs(auth.uid())) WITH CHECK(public.can_see_costs(auth.uid()));
CREATE TRIGGER entries_audit BEFORE INSERT OR UPDATE ON public.financial_entries FOR EACH ROW EXECUTE FUNCTION public.touch_audit();
CREATE TABLE public.financial_settlements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entry_id uuid NOT NULL REFERENCES public.financial_entries(id), account_id uuid NOT NULL REFERENCES public.financial_accounts(id), amount numeric NOT NULL CHECK(amount>0), paid_date date NOT NULL, file_path text, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.financial_settlements TO authenticated; GRANT ALL ON public.financial_settlements TO service_role;
ALTER TABLE public.financial_settlements ENABLE ROW LEVEL SECURITY;
CREATE POLICY settlements_access ON public.financial_settlements FOR ALL TO authenticated USING(public.can_see_costs(auth.uid())) WITH CHECK(public.can_see_costs(auth.uid()));
CREATE TABLE public.account_transfers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), from_account_id uuid NOT NULL REFERENCES public.financial_accounts(id), to_account_id uuid NOT NULL REFERENCES public.financial_accounts(id), amount numeric NOT NULL CHECK(amount>0), transfer_date date NOT NULL, description text, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), CHECK(from_account_id<>to_account_id));
GRANT SELECT, INSERT ON public.account_transfers TO authenticated; GRANT ALL ON public.account_transfers TO service_role;
ALTER TABLE public.account_transfers ENABLE ROW LEVEL SECURITY;
CREATE POLICY transfers_access ON public.account_transfers FOR ALL TO authenticated USING(public.can_see_costs(auth.uid())) WITH CHECK(public.can_see_costs(auth.uid()));
CREATE TABLE public.expense_allocations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entry_id uuid NOT NULL REFERENCES public.financial_entries(id), work_id uuid NOT NULL REFERENCES public.works(id), amount numeric NOT NULL CHECK(amount>0), rule text NOT NULL, UNIQUE(entry_id,work_id));
GRANT SELECT, INSERT ON public.expense_allocations TO authenticated; GRANT ALL ON public.expense_allocations TO service_role;
ALTER TABLE public.expense_allocations ENABLE ROW LEVEL SECURITY;
CREATE POLICY allocations_access ON public.expense_allocations FOR ALL TO authenticated USING(public.can_see_costs(auth.uid())) WITH CHECK(public.can_see_costs(auth.uid()));
CREATE TABLE public.work_extras (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), work_id uuid NOT NULL REFERENCES public.works(id), description text NOT NULL, cost numeric NOT NULL DEFAULT 0 CHECK(cost>=0), price numeric NOT NULL DEFAULT 0 CHECK(price>=0), extra_days int NOT NULL DEFAULT 0, approved boolean NOT NULL DEFAULT false, approval_date date, file_path text, created_by uuid, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.work_extras TO authenticated; GRANT ALL ON public.work_extras TO service_role;
ALTER TABLE public.work_extras ENABLE ROW LEVEL SECURITY;
CREATE POLICY extras_access ON public.work_extras FOR ALL TO authenticated USING(public.can_see_costs(auth.uid())) WITH CHECK(public.can_see_costs(auth.uid()));
CREATE TRIGGER extras_audit BEFORE INSERT OR UPDATE ON public.work_extras FOR EACH ROW EXECUTE FUNCTION public.touch_audit();
CREATE TABLE public.work_estimates (work_id uuid PRIMARY KEY REFERENCES public.works(id), additional_cost numeric NOT NULL DEFAULT 0 CHECK(additional_cost>=0), notes text);
GRANT SELECT, INSERT, UPDATE ON public.work_estimates TO authenticated; GRANT ALL ON public.work_estimates TO service_role;
ALTER TABLE public.work_estimates ENABLE ROW LEVEL SECURITY;
CREATE POLICY estimates_access ON public.work_estimates FOR ALL TO authenticated USING(public.can_see_costs(auth.uid())) WITH CHECK(public.can_see_costs(auth.uid()));
CREATE OR REPLACE FUNCTION public.guard_budget_locked() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE st public.budget_status; BEGIN IF tg_table_name='budgets' THEN IF old.status IN ('aprovado','recusado') AND (to_jsonb(new)-ARRAY['archived','updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(old)-ARRAY['archived','updated_at','updated_by']) THEN RAISE EXCEPTION 'Orçamento bloqueado. Crie uma revisão.'; END IF; IF new.status='aprovado' AND (new.approval_date IS NULL OR nullif(new.approval_path,'') IS NULL) THEN RAISE EXCEPTION 'Informe data e comprovante de aprovação.'; END IF; RETURN new; END IF; SELECT status INTO st FROM public.budgets WHERE id=coalesce(new.budget_id,old.budget_id); IF st IN ('aprovado','recusado') THEN RAISE EXCEPTION 'Orçamento bloqueado. Crie uma revisão.'; END IF; RETURN coalesce(new,old); END $$;
CREATE OR REPLACE FUNCTION public.convert_budget(_budget_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE b public.budgets; wid uuid; BEGIN IF NOT public.can_see_costs(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão'; END IF; SELECT * INTO b FROM public.budgets WHERE id=_budget_id FOR UPDATE; IF NOT FOUND OR b.status<>'aprovado' THEN RAISE EXCEPTION 'Aprove o orçamento antes de converter.'; END IF; SELECT id INTO wid FROM public.works WHERE budget_id=b.id; IF wid IS NOT NULL THEN RETURN wid; END IF; INSERT INTO public.works(budget_id,name,client_id,architect_id,address) VALUES(b.id,coalesce(nullif(b.title,''),'Obra')||' · '||coalesce(b.client_display,''),b.client_id,b.architect_id,concat_ws(', ',b.endereco,b.bairro,b.cidade,b.uf,b.cep)) RETURNING id INTO wid; INSERT INTO public.work_stages(work_id,budget_section_id,name,sort) SELECT wid,id,title,sort FROM public.budget_sections WHERE budget_id=b.id; INSERT INTO public.budget_history(budget_id,action,summary) VALUES(b.id,'convertido_em_obra',jsonb_build_object('work_id',wid)); RETURN wid; END $$;
REVOKE ALL ON FUNCTION public.convert_budget(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.convert_budget(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_contract() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF old.status='assinado' THEN RAISE EXCEPTION 'Contrato assinado preservado. Registre um aditivo.'; END IF; IF new.status IN ('gerado','assinado') AND (nullif(trim(new.body),'') IS NULL OR new.body ~ '\{\{[^}]+\}\}') THEN RAISE EXCEPTION 'Preencha todos os dados do contrato.'; END IF; IF new.status='assinado' AND (new.signed_date IS NULL OR nullif(new.signed_path,'') IS NULL) THEN RAISE EXCEPTION 'Anexe o contrato assinado e a data.'; END IF; RETURN new; END $$;
CREATE TRIGGER contract_guard BEFORE UPDATE ON public.contracts FOR EACH ROW EXECUTE FUNCTION public.guard_contract();
CREATE OR REPLACE FUNCTION public.guard_settlement() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE e public.financial_entries; total numeric; BEGIN SELECT * INTO e FROM public.financial_entries WHERE id=new.entry_id FOR UPDATE; IF e.canceled THEN RAISE EXCEPTION 'Conta cancelada.'; END IF; SELECT coalesce(sum(amount),0) INTO total FROM public.financial_settlements WHERE entry_id=e.id; IF total+new.amount>e.amount THEN RAISE EXCEPTION 'Baixa maior que o saldo pendente.'; END IF; RETURN new; END $$;
CREATE TRIGGER settlement_guard BEFORE INSERT ON public.financial_settlements FOR EACH ROW EXECUTE FUNCTION public.guard_settlement();
CREATE OR REPLACE FUNCTION public.guard_allocation() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE e public.financial_entries; total numeric; BEGIN SELECT * INTO e FROM public.financial_entries WHERE id=new.entry_id FOR UPDATE; IF e.work_id IS NOT NULL OR e.direction<>'saida' OR e.purchase_order_id IS NOT NULL THEN RAISE EXCEPTION 'Rateie apenas despesas gerais sem obra.'; END IF; SELECT coalesce(sum(amount),0) INTO total FROM public.expense_allocations WHERE entry_id=e.id; IF total+new.amount>e.amount THEN RAISE EXCEPTION 'Rateio excede a despesa.'; END IF; RETURN new; END $$;
CREATE TRIGGER allocation_guard BEFORE INSERT ON public.expense_allocations FOR EACH ROW EXECUTE FUNCTION public.guard_allocation();
CREATE OR REPLACE FUNCTION public.guard_stage_dependency() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE dep public.work_stages; cycle boolean; BEGIN IF new.planned_end<new.planned_start THEN RAISE EXCEPTION 'Término anterior ao início.'; END IF; IF new.dependency_id IS NOT NULL THEN SELECT * INTO dep FROM public.work_stages WHERE id=new.dependency_id; IF dep.work_id<>new.work_id OR dep.id=new.id THEN RAISE EXCEPTION 'Dependência inválida.'; END IF; WITH RECURSIVE chain AS (SELECT id,dependency_id FROM public.work_stages WHERE id=new.dependency_id UNION SELECT s.id,s.dependency_id FROM public.work_stages s JOIN chain c ON s.id=c.dependency_id) SELECT exists(SELECT 1 FROM chain WHERE id=new.id) INTO cycle; IF cycle THEN RAISE EXCEPTION 'Dependência circular.'; END IF; END IF; RETURN new; END $$;
CREATE TRIGGER dependency_guard BEFORE INSERT OR UPDATE ON public.work_stages FOR EACH ROW EXECUTE FUNCTION public.guard_stage_dependency();
CREATE OR REPLACE FUNCTION public.guard_extra() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND old.approved THEN RAISE EXCEPTION 'Aditivo aprovado preservado. Registre outro aditivo.'; END IF; IF new.approved AND (new.approval_date IS NULL OR nullif(new.file_path,'') IS NULL) THEN RAISE EXCEPTION 'Informe data e comprovante do aditivo.'; END IF; RETURN new; END $$;
CREATE TRIGGER extra_guard BEFORE INSERT OR UPDATE ON public.work_extras FOR EACH ROW EXECUTE FUNCTION public.guard_extra();
CREATE POLICY jmg_docs_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='jmg-documents' AND (public.can_see_costs(auth.uid()) OR (public.has_role(auth.uid(),'equipe') AND (storage.foldername(name))[1]='records')));
CREATE POLICY jmg_docs_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='jmg-documents' AND (public.can_see_costs(auth.uid()) OR (public.has_role(auth.uid(),'equipe') AND (storage.foldername(name))[1]='records')));
CREATE POLICY jmg_docs_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='jmg-documents' AND owner_id=auth.uid()::text);
CREATE INDEX work_records_work_idx ON public.work_records(work_id,kind);
CREATE INDEX financial_entries_work_idx ON public.financial_entries(work_id,due_date);
CREATE INDEX purchase_orders_work_idx ON public.purchase_orders(work_id);